def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def fill_color(inner_height, inner_width):
        size = max(inner_height, inner_width)
        return {3: 8, 5: 4, 7: 3}.get(size, 8)

    for top in range(h):
        for bottom in range(top + 4, h):
            for left in range(w):
                for right in range(left + 4, w):
                    if not (
                        all(grid[top][c] == 2 and grid[bottom][c] == 2
                            for c in range(left, right + 1))
                        and all(grid[r][left] == 2 and grid[r][right] == 2
                                for r in range(top, bottom + 1))
                    ):
                        continue

                    marks = [
                        (r, c)
                        for r in range(top + 1, bottom)
                        for c in range(left + 1, right)
                        if grid[r][c] == 2
                    ]
                    if len(marks) != 1:
                        continue

                    color = fill_color(bottom - top - 1, right - left - 1)
                    for r in range(top + 1, bottom):
                        for c in range(left + 1, right):
                            if grid[r][c] == 0:
                                out[r][c] = color

    return out
